.venv/bin/python - <<'EOF'
import json
src = open('autoresearch/figcheck.py').read()
ns = {'__name__': 'figcheck_dbg'}
exec(compile(src, 'figcheck.py', 'exec'), ns)
svg = json.load(open('side_track/refigure_26_30/exp29/figure.json'))['architecture_svg']
boxes = [b for b in ns['_text_boxes'](svg) if 'abstain' in b[4]]
print(boxes)
for seg in ns['_segments'](svg):
    for box in boxes:
        if ns['_inside'](seg[:2], box) or ns['_inside'](seg[2:], box):
            continue
        L = ns['_clip_len'](seg, box)
        if L > 12:
            print('CROSS', seg, L)
EOF
